  add('volume','standard','直方体のたての長さだけを２倍にして、横と高さはそのままにすると、体積はどうなりますか。','２倍になる',['変わらない','４倍になる','半分になる'],['体積＝たて×横×高さです。','たてが２倍なら、答えも２倍になります。'],'たて×横×高さの、たてだけが２倍になるので、体積も２倍になります。');
  add('volume','standard','底面積が24cm²で、高さが５cmの直方体の体積は何cm³ですか。',120,[29,48,60],['体積＝底面積×高さです。','底面積は、たて×横の部分です。'],'24 × 5＝120。体積は120cm³です。');
  add('volume','standard','体積が72cm³で、底面積が18cm²の直方体があります。高さは何cmですか。',4,[3,54,6],['体積＝底面積×高さです。','体積を底面積でわります。'],'72 ÷ 18＝４。高さは４cmです。');

  add('volume','advanced','立方体の、たて・横・高さを、すべて２倍にすると、体積は何倍になりますか。',8,[2,4,6],['１辺が１cmの立方体を、２cmにしてみましょう。','２×２×２ を計算します。'],'体積は、たて×横×高さなので、２倍 × ２倍 × ２倍＝８倍になります。');
  add('volume','advanced','たて６cm、横５cm、高さ４cmの直方体の、すみから、１辺２cmの立方体を切り取ります。のこった立体の体積は何cm³ですか。',112,[120,8,128],['もとの直方体の体積を求めます。','切り取った立方体の体積を引きます。'],'6 × 5 × 4＝120cm³、2 × 2 × 2＝８cm³。120－８＝112。体積は112cm³です。');
  add('volume','advanced','底が、たて50cm、横40cmの水そうに水が入っています。石を{沈|しず}めたら、水面が２cm上がりました。石の体積は何cm³ですか。',4000,[2000,400,40000],['上がった部分の水の体積が、石の体積です。','底の面積に、上がった高さをかけます。'],'50 × 40 × 2＝4000。石の体積は4000cm³です。');
  add('volume','advanced','底が、たて30cm、横20cmの水そうに、深さ12cmまで水が入っています。体積1200cm³の氷のブロックを全部{沈|しず}めると、水の深さは何cmになりますか。',14,[2,12,16],['氷を{沈|しず}めると、水面が何cm上がるか考えます。','底の面積は 30 × 20＝600cm² です。'],'1200 ÷ 600＝２。水面は２cm上がるので、12＋２＝14。深さは14cmです。');
  add('volume','advanced','たて３cm、横４cm、高さ２cmの直方体と、たて３cm、横２cm、高さ５cmの直方体をくっつけました。全体の体積は何cm³ですか。',54,[24,30,60],['それぞれの体積を求めます。','２つの体積を足します。'],'3 × 4 × 2＝24cm³、3 × 2 × 5＝30cm³。24＋30＝54。全体の体積は54cm³です。');
  add('volume','advanced','１辺が６cmの立方体を、１辺が２cmの立方体に切り分けます。小さい立方体は全部で何こできますか。',27,[3,9,18],['１辺に、小さい立方体が何こならぶか考えます。','６÷２＝３こです。'],'たて、横、高さに、３こずつならびます。3 × 3 × 3＝27こできます。');
  add('volume','advanced','たて50cm、横30cmの底の水そうに、毎分３Lずつ水を入れます。深さが20cmになるまでには、何分かかりますか。',10,[3,20,30],['深さ20cmの水の体積を、まず求めます。','Lになおして、１分間に入れる量でわります。'],'50 × 30 × 20＝30000cm³＝30L。30 ÷ 3＝10。10分かかります。');
  add('volume','advanced','底が、たて40cm、横30cmの水そうに、24Lの水を入れました。水の深さは何cmですか。',20,[8,12,24],['24L＝24000cm³ です。','底の面積でわると、深さになります。'],'24L＝24000cm³。底の面積は 40 × 30＝1200cm²。24000 ÷ 1200＝20。深さは20cmです。');
  add('volume','advanced','体積が48cm³で、たてが４cm、高さが３cmの直方体があります。横は何cmですか。',4,[2,6,16],['たて×高さを先に求めます。','体積を、たて×高さでわります。'],'4 × 3＝12。48 ÷ 12＝４。横は４cmです。');
  add('volume','advanced','１辺が10cmの立方体から、１辺が５cmの立方体をくりぬきます。のこった立体の体積は何cm³ですか。',875,[125,1000,500],['どちらの立方体の体積も求めます。','大きい体積から小さい体積を引きます。'],'10 × 10 × 10＝1000cm³、5 × 5 × 5＝125cm³。1000－125＝875。体積は875cm³です。');
  add('volume','advanced','たて２m、横１m、高さ50cmのプールがあります。いっぱいに水を入れると、水は何Lですか。',1000,[100,10000,2000],['高さ50cmは、0.5mです。','m³ で体積を求めて、Lにします。'],'2 × 1 × 0.5＝１m³。１m³は1000Lなので、1000Lです。');

  // ---- 図形の角：基礎9・標準15・発展12 ----
  add('angle','basic','三角形の３つの角の大きさの和は、何度ですか。',180,[90,270,360],['三角形は、どんな形でも同じ和になります。','紙で三角形を作り、角を切って合わせると一直線になります。'],'三角形の３つの角の和は、いつも180°です。');
  add('angle','basic','四角形の４つの角の大きさの和は、何度ですか。',360,[180,270,720],['四角形は、対角線で２つの三角形に分けられます。','三角形の角の和は180°です。'],'四角形は、２つの三角形に分けられるので、180° × 2＝360°です。');
  add('angle','basic','三角形の２つの角が、50°と60°です。のこりの１つの角は何度ですか。',70,[110,130,10],['３つの角の和は180°です。','180°から、わかっている角を引きます。'],'50＋60＝110。180－110＝70。のこりの角は70°です。');
  add('angle','basic','三角形の２つの角が、90°と35°です。のこりの１つの角は何度ですか。',55,[45,125,65],['３つの角の和は180°です。','90＋35 を先に計算します。'],'90＋35＝125。180－125＝55。のこりの角は55°です。');
  add('angle','basic','正三角形の１つの角は、何度ですか。',60,[30,45,90],['正三角形は、３つの角が同じ大きさです。','３つの角の和は180°です。'],'180 ÷ 3＝60。１つの角は60°です。');
  add('angle','basic','四角形の３つの角が、90°、80°、100°です。のこりの１つの角は何度ですか。',90,[70,80,100],['４つの角の和は360°です。','90＋80＋100 を先に計算します。'],'90＋80＋100＝270。360－270＝90。のこりの角は90°です。');
  add('angle','basic','五角形の５つの角の大きさの和は、何度ですか。',540,[360,450,720],['五角形は、３つの三角形に分けられます。','180° × 3 を計算します。'],'五角形は、１つの頂点から対角線をひくと、３つの三角形に分けられます。180 × 3＝540。和は540°です。');
  add('angle','basic','三角形の２つの角が、45°と45°です。のこりの１つの角は何度ですか。',90,[45,60,180],['３つの角の和は180°です。','45＋45 を先に計算します。'],'45＋45＝90。180－90＝90。のこりの角は90°です。');
  add('angle','basic','三角形の２つの角が、70°と40°です。のこりの１つの角は何度ですか。',70,[110,30,140],['３つの角の和は180°です。','70＋40 を先に計算します。'],'70＋40＝110。180－110＝70。のこりの角は70°です。');

  add('angle','standard','二等辺三角形で、{頂角|ちょうかく}が80°のとき、底角は何度ですか。',50,[100,80,40],['二等辺三角形の底角は、同じ大きさです。','180°から{頂角|ちょうかく}を引いて、２でわります。'],'180－80＝100。100 ÷ 2＝50。底角は50°です。');
  add('angle','standard','二等辺三角形で、底角が65°のとき、{頂角|ちょうかく}は何度ですか。',50,[65,115,130],['底角は２つあって、同じ大きさです。','180°から、底角２つ分を引きます。'],'65 × 2＝130。180－130＝50。{頂角|ちょうかく}は50°です。');
  add('angle','standard','六角形の６つの角の大きさの和は、何度ですか。',720,[540,360,1080],['六角形は、１つの頂点から対角線をひくと、いくつの三角形に分けられるでしょう。','三角形の数に、180°をかけます。'],'六角形は４つの三角形に分けられます。180 × 4＝720。和は720°です。');
  add('angle','standard','正五角形の１つの角は、何度ですか。',108,[72,120,90],['五角形の角の和は540°です。','正五角形は、５つの角が同じ大きさです。'],'540 ÷ 5＝108。１つの角は108°です。');
  add('angle','standard','四角形の３つの角が、75°、110°、95°です。のこりの１つの角は何度ですか。',80,[70,90,280],['４つの角の和は360°です。','75＋110＋95 を先に計算します。'],'75＋110＋95＝280。360－280＝80。のこりの角は80°です。');
  add('angle','standard','正六角形の１つの角は、何度ですか。',120,[60,108,135],['六角形の角の和は720°です。','正六角形は、６つの角が同じ大きさです。'],'720 ÷ 6＝120。１つの角は120°です。');
  add('angle','standard','十角形の10この角の大きさの和は、何度ですか。',1440,[1080,1260,1800],['十角形は、１つの頂点から対角線をひくと、８つの三角形に分けられます。','180 × 8 を計算します。'],'180 × 8＝1440。和は1440°です。');
  add('angle','standard','平行四辺形ＡＢＣＤで、角Ａが65°のとき、角Ｂは何度ですか。',115,[65,125,25],['平行四辺形では、となりあう角の和は180°です。','180°から、角Ａを引きます。'],'180－65＝115。角Ｂは115°です。');
  add('angle','standard','八角形の８この角の大きさの和は、何度ですか。',1080,[720,960,1260],['八角形は、６つの三角形に分けられます。','180 × 6 を計算します。'],'180 × 6＝1080。和は1080°です。');
  add('angle','standard','直角三角形があります。直角ではない角の１つが30°のとき、もう１つの角は何度ですか。',60,[30,45,150],['直角は90°です。','３つの角の和は180°です。'],'180－90－30＝60。もう１つの角は60°です。');
  add('angle','standard','ひし形の１つの角が50°のとき、そのとなりの角は何度ですか。',130,[50,40,310],['ひし形は平行四辺形のなかまです。','となりあう角の和は180°です。'],'180－50＝130。となりの角は130°です。');
  add('angle','standard','台形ＡＢＣＤで、辺ＡＤと辺ＢＣが平行です。角Ａが100°のとき、角Ｂは何度ですか。',80,[100,260,90],['平行な辺にはさまれた、同じ側の角の和は180°です。','180°から、角Ａを引きます。'],'ＡＤとＢＣが平行なので、角Ａ＋角Ｂ＝180°。180－100＝80。角Ｂは80°です。');
  add('angle','standard','五角形の４つの角が、100°、110°、120°、90°です。のこりの１つの角は何度ですか。',120,[100,540,420],['五角形の５つの角の和は540°です。','４つの角の和を先に求めます。'],'100＋110＋120＋90＝420。540－420＝120。のこりの角は120°です。');
  add('angle','standard','二等辺三角形で、{頂角|ちょうかく}が、底角の２倍のとき、底角は何度ですか。',45,[60,90,30],['底角を１とすると、{頂角|ちょうかく}は２です。','１＋１＋２＝４が180°にあたります。'],'底角２つ分と{頂角|ちょうかく}で、底角の４つ分が180°です。180 ÷ 4＝45。底角は45°です。');
  add('angle','standard','正方形に対角線をひくと、２つの三角形ができます。そのうちの、対角線と辺でできる角は何度ですか。',45,[30,60,90],['正方形の角は90°です。','対角線は、その角を２つに等しく分けます。'],'90 ÷ 2＝45。角は45°です。');

  add('angle','advanced','正八角形の１つの角は、何度ですか。',135,[120,108,150],['八角形の角の和は1080°です。','正八角形は、８つの角が同じ大きさです。'],'1080 ÷ 8＝135。１つの角は135°です。');
  add('angle','advanced','正十二角形の１つの角は、何度ですか。',150,[120,135,144],['十二角形は、10この三角形に分けられます。','角の和を、12でわります。'],'180 × 10＝1800。1800 ÷ 12＝150。１つの角は150°です。');
  add('angle','advanced','多角形の角の大きさの和が1980°のとき、この多角形の辺の数はいくつですか。',13,[11,12,15],['n角形の角の和は、180 × (n－2) です。','1980 ÷ 180 を先に計算します。'],'1980 ÷ 180＝11。三角形の数が11こなので、辺の数は 11＋2＝13です。十三角形です。');
  add('angle','advanced','多角形の角の大きさの和が1260°のとき、この多角形の辺の数はいくつですか。',9,[7,8,10],['n角形の角の和は、180 × (n－2) です。','1260 ÷ 180 を先に計算します。'],'1260 ÷ 180＝７。三角形の数が７こなので、辺の数は 7＋2＝９です。九角形です。');
  add('angle','advanced','三角形ＡＢＣで、角Ａが60°、角Ｂが角Ｃの２倍です。角Ｂは何度ですか。',80,[40,60,120],['角Ｂ＋角Ｃは、180°から角Ａを引いて求めます。','角Ｃを１とすると、角Ｂは２です。'],'180－60＝120。角Ｂ＋角Ｃ＝120°で、角Ｃの３つ分にあたります。角Ｃは40°、角Ｂは80°です。');
  add('angle','advanced','五角形を、１つの頂点から出る対角線で三角形に分けると、三角形はいくつできますか。',3,[2,4,5],['五角形の頂点から、ひける対角線の数を考えます。','対角線の数に１を足します。'],'１つの頂点から対角線は２本ひけます。三角形は 2＋1＝３こできます。');
  add('angle','advanced','六角形で、１つの頂点からひける対角線は何本ですか。',3,[2,4,6],['となりの頂点と、その頂点自身には対角線をひけません。','頂点の数から３を引きます。'],'６つの頂点のうち、自分とそのとなりの２つをのぞく、6－3＝３本です。');
  add('angle','advanced','七角形の対角線は、全部で何本ありますか。',14,[7,21,28],['１つの頂点から、７－３＝４本ひけます。','頂点が７つあるので、２回数えた分を２でわります。'],'１つの頂点から４本。7 × 4＝28。同じ対角線を２回ずつ数えているので、28 ÷ 2＝14本です。');
  add('angle','advanced','正五角形で、１つの頂点から、２本の対角線をひきました。２本の対角線にはさまれた、まん中の角は何度ですか。（３つに分かれた角は、すべて同じ大きさです）',36,[18,54,72],['正五角形の１つの角は108°です。','その角が、３つの等しい角に分かれています。'],'正五角形の１つの角は108°。108 ÷ 3＝36。まん中の角は36°です。');
  add('angle','advanced','三角形で、１つの角の大きさが、ほかの２つの角の和と同じです。この角は何度ですか。',90,[60,120,180],['この角をアとすると、３つの角の和は ア＋ア＝２アです。','２ア＝180° になります。'],'ア＋（ほかの２つの和）＝180°で、（ほかの２つの和）＝アなので、アが２つ分で180°。ア＝90°です。');
  add('angle','advanced','平行四辺形ＡＢＣＤで、角Ａが70°のとき、角Ｂと角Ｄの和は何度ですか。',220,[110,140,180],['平行四辺形のとなりあう角の和は180°です。','向かい合う角は同じ大きさです。'],'角Ｂは180－70＝110°。角Ｄも110°。110＋110＝220。和は220°です。');
  add('angle','advanced','星の形（{五芒星|ごぼうせい}）の、５つのとがった先の角の大きさの和は、何度ですか。',180,[360,540,720],['星の形の中には、いくつかの三角形が見えます。','となりあう先の角どうしの外側の角を使うと、三角形の角の和を使えます。'],'星の先の５つの角の和は、いつも180°になります。（正五角形の星では、１つの先の角が36°なので、36 × 5＝180°です。）');

  // ---- 合同な図形：基礎6・標準9・発展7 ----
  add('congruent','basic','ぴったり重ね合わせることができる、２つの図形のことを何といいますか。','合同な図形',['相似な図形','{対称|たいしょう}な図形','平行な図形'],['形も大きさも同じ図形です。','うら返して重ねてもかまいません。'],'ぴったり重なる２つの図形を、合同な図形といいます。');
  add('congruent','basic','合同な図形を重ねたとき、重なり合う頂点を何といいますか。','対応する頂点',['平行な頂点','ひとしい頂点','となりあう頂点'],['重なる辺は「対応する辺」、重なる角は「対応する角」です。','頂点は、重なる点のことです。'],'重なり合う頂点は「対応する頂点」といいます。辺は「対応する辺」、角は「対応する角」です。');
  add('congruent','basic','合同な２つの三角形で、対応する辺の長さは、どうなっていますか。','等しい',['２倍になっている','半分になっている','ちがっている'],['合同な図形は、ぴったり重なります。','重なる辺は、長さも同じです。'],'ぴったり重なるので、対応する辺の長さは等しくなっています。');
  add('congruent','basic','四角形ＡＢＣＤと四角形ＥＦＧＨは合同です。辺ＡＢが５cmのとき、辺ＥＦは何cmですか。',5,[10,2.5,15],['辺ＡＢに対応する辺はどれでしょう。','Ａ→Ｅ、Ｂ→Ｆ と対応しています。'],'辺ＡＢと辺ＥＦは対応する辺なので、長さは等しく５cmです。');
  add('congruent','basic','合同な２つの図形で、対応する角の大きさは、どうなっていますか。','等しい',['２倍になっている','半分になっている','ちがっている'],['ぴったり重なります。','重なる角は、同じ大きさです。'],'ぴったり重なるので、対応する角の大きさは等しくなっています。');
  add('congruent','basic','合同な図形は、うら返して重ねてぴったり重なる場合も、合同といえますか。','いえる',['いえない','三角形のときだけいえる','四角形のときだけいえる'],['向きを変えたり、うら返したりしても、形と大きさは変わりません。','動かして重なれば、合同です。'],'うら返してぴったり重なる図形も、合同な図形といえます。');

  add('congruent','standard','三角形ＡＢＣと三角形ＤＥＦは合同です。角Ａが70°のとき、角Ｄは何度ですか。',70,[110,35,20],['Ａ→Ｄと対応しています。','対応する角の大きさは等しいです。'],'角Ａと角Ｄは対応する角なので、大きさは等しく70°です。');
  add('congruent','standard','辺の長さが、３cm、４cm、５cmの三角形が２つあります。この２つは合同といえますか。','いえる',['いえない','角の大きさがわからないのでいえない','もう１つ条件がないといえない'],['３つの辺の長さが等しい三角形は、形が１つに決まります。','三角形の合同の条件を思い出しましょう。'],'３つの辺の長さがそれぞれ等しい２つの三角形は合同です。');
  add('congruent','standard','三角形の合同を調べるとき、これだけでは合同とはいえないものはどれですか。','３つの角の大きさがそれぞれ等しい',['３つの辺の長さがそれぞれ等しい','２つの辺の長さと、その間の角の大きさがそれぞれ等しい','１つの辺の長さと、その両はしの角の大きさがそれぞれ等しい'],['角の大きさが同じでも、大きさがちがう三角形があります。','大きい三角形と小さい三角形で、角が同じ場合を考えます。'],'３つの角が等しくても、大きさのちがう三角形があるので、合同とはいえません。');
  add('congruent','standard','１つの辺が４cmで、その両はしの角が50°と60°の三角形をかきます。のこりの角は何度ですか。',70,[40,110,130],['三角形の３つの角の和は180°です。','50＋60 を先に計算します。'],'50＋60＝110。180－110＝70。のこりの角は70°です。');
  add('congruent','standard','四角形ＡＢＣＤと四角形ＥＦＧＨは合同です。辺ＢＣが６cmのとき、辺ＦＧは何cmですか。',6,[12,3,9],['Ｂ→Ｆ、Ｃ→Ｇ と対応しています。','対応する辺の長さは等しいです。'],'辺ＢＣと辺ＦＧは対応する辺なので、長さは等しく６cmです。');
  add('congruent','standard','正方形に対角線を１本ひいて、２つの三角形に分けました。この２つの三角形は、合同ですか。','合同である',['合同ではない','大きさだけが同じ','形だけが同じ'],['折ると、ぴったり重なるか考えます。','３つの辺の長さが、それぞれ等しいか調べます。'],'３つの辺の長さがそれぞれ等しいので、合同です。（対角線を折り目にして重ねることもできます。）');
  add('congruent','standard','平行四辺形に対角線を１本ひいて、２つの三角形に分けました。この２つの三角形は、合同ですか。','合同である',['合同ではない','面積だけが同じ','合同とは限らない'],['平行四辺形は、向かい合う辺の長さが等しいです。','対角線は、２つの三角形に共通な辺です。'],'向かい合う辺の長さが等しく、対角線は共通なので、３つの辺がそれぞれ等しい三角形になります。合同です。');
  add('congruent','standard','合同な２つの図形の面積について、正しいものはどれですか。','等しい',['どちらかが大きい','２倍になる','わからない'],['ぴったり重なる図形の大きさを考えます。','重なれば、広さも同じです。'],'合同な図形はぴったり重なるので、面積も等しくなります。');
  add('congruent','standard','三角形ＡＢＣと三角形ＤＥＦは合同です。三角形ＡＢＣのまわりの長さが12cmのとき、三角形ＤＥＦのまわりの長さは何cmですか。',12,[6,24,36],['対応する辺の長さは、それぞれ等しいです。','３つの辺の長さの和も等しくなります。'],'対応する辺の長さが等しいので、まわりの長さも等しく12cmです。');

  add('congruent','advanced','三角形ＡＢＣは、角Ａが80°、角Ｂが50°です。三角形ＤＥＦは、角Ｄが80°、角Ｅが50°です。この２つの三角形は、合同といえますか。','合同とは限らない',['必ず合同である','合同ではない','角Ｃが等しくないので合同ではない'],['３つの角が等しくても、大きさがちがう三角形があります。','辺の長さについては、何もわかっていません。'],'３つの角が等しくても、辺の長さがわからないので、合同とは限りません。大きい三角形と小さい三角形のこともあります。');
  add('congruent','advanced','三角形ＡＢＣと三角形ＰＱＲは合同で、辺ＡＢ＝５cm、辺ＢＣ＝７cm、辺ＣＡ＝６cmです。Ａ→Ｐ、Ｂ→Ｑ、Ｃ→Ｒと対応するとき、辺ＱＲは何cmですか。',7,[5,6,18],['辺ＱＲに対応する辺はどれでしょう。','Ｑ→Ｂ、Ｒ→Ｃです。'],'辺ＱＲは辺ＢＣと対応するので、７cmです。');
  add('congruent','advanced','４つの辺の長さが、すべて等しい四角形が２つあります。この２つは、必ず合同といえますか。','合同とは限らない',['必ず合同である','合同ではない','どちらも正方形だから合同'],['ひし形は、４つの辺が等しい四角形です。','ひし形は、角の大きさをかえることができます。'],'４つの辺が等しくても、角の大きさがちがうひし形があるので、合同とは限りません。');
  add('congruent','advanced','三角形ＡＢＣと三角形ＤＥＦで、辺ＡＢ＝辺ＤＥ＝５cm、角Ａ＝角Ｄ＝40°、辺ＡＣ＝辺ＤＦ＝７cmです。この２つの三角形が合同といえる理由は、どれですか。','２つの辺の長さと、その間の角の大きさがそれぞれ等しいから',['３つの角の大きさがそれぞれ等しいから','３つの辺の長さがそれぞれ等しいから','１つの辺の長さと、その両はしの角がそれぞれ等しいから'],['角Ａと角Ｄは、どの辺にはさまれているでしょう。','わかっているのは、辺２つと角１つです。'],'角Ａは、辺ＡＢと辺ＡＣにはさまれています。２つの辺と、その間の角がそれぞれ等しいので合同です。');
  add('congruent','advanced','次の条件のうち、形が１つに決まる三角形をかけるものはどれですか。','辺が４cm、５cmで、その間の角が60°',['３つの角が60°、60°、60°','辺が５cm、５cmだけ','辺が４cm、角が40°だけ'],['三角形が１つに決まるには、合同の条件にあてはまる必要があります。','辺が２つと、その間の角がわかると決まります。'],'「２つの辺とその間の角」がわかると、三角形は１つに決まります。ほかは、大きさや形がいくつもできてしまいます。');
  add('congruent','advanced','平行四辺形ＡＢＣＤに対角線ＡＣをひきました。三角形ＡＢＣと三角形ＣＤＡは合同です。辺ＡＢに対応する辺はどれですか。','辺ＣＤ',['辺ＢＣ','辺ＤＡ','辺ＡＣ'],['Ａ→Ｃ、Ｂ→Ｄ、Ｃ→Ａ と対応しています。','三角形ＡＢＣと三角形ＣＤＡの、頂点の順番を見ます。'],'三角形ＡＢＣと三角形ＣＤＡは、Ａ→Ｃ、Ｂ→Ｄと対応します。辺ＡＢは辺ＣＤに対応します。');
  add('congruent','advanced','たて４cm、横７cmの長方形を、合同な長方形２つにして、横にくっつけて大きな長方形を作ります。大きな長方形のまわりの長さは何cmですか。',36,[22,44,56],['くっつけると、横の長さが何cmになるでしょう。','たて×２＋横×２で、まわりの長さを求めます。'],'横は 7 × 2＝14cm、たては４cm。まわりの長さは (4＋14) × 2＝36cm です。');

  // ---- 比例：基礎6・標準9・発展7 ----
  add('proportion','basic','xが２倍、３倍、…になると、それにともなってyも２倍、３倍、…になるとき、yはxにどうなっているといいますか。','比例している',['反比例している','等しい','関係がない'],['xとyが同じ割合で増えているかを見ます。','２倍になれば２倍、３倍になれば３倍になる関係です。'],'yがxと同じ割合で増えたり減ったりするとき、「yはxに比例している」といいます。');
  add('proportion','basic','yはxに比例していて、y＝２×xです。xが４のとき、yはいくつですか。',8,[6,2,16],['xに４を入れて計算します。','２×４です。'],'y＝2 × 4＝８です。');
  add('proportion','basic','１本５円のえんぴつを、x本買ったときの代金をy円とします。xが４のとき、yはいくつですか。',20,[9,5,45],['代金＝１本のねだん×本数です。','５×４を計算します。'],'5 × 4＝20。代金は20円です。');
  add('proportion','basic','xとyの関係が表のようになっています。xが５のとき、yはいくつですか。',15,[12,18,5],['xが１ふえると、yがいくつふえているか見ます。','yは３ずつふえています。'],'xが１ふえるごとにyは３ふえています。x＝４のとき12なので、x＝５のときは15です。（y＝３×xです。）',{kind:'table',head:['x','１','２','３','４'],rows:[['y','３','６','９','12']],caption:'xとyの関係'});
  add('proportion','basic','比例のグラフは、どんな形になりますか。','０の点を通る直線',['０の点を通らない直線','まがった線','たての直線'],['xが０のときのyを考えます。','比例のグラフは、まっすぐな線になります。'],'比例のグラフは、０の点を通る直線になります。');
  add('proportion','basic','次のうち、yがxに比例しているものはどれですか。','正方形の１辺x cmと、まわりの長さy cm',['正方形の１辺x cmと、面積y cm²','弟の年れいx才と、兄の年れいy才','人の年れいx才と、身長y cm'],['xが２倍になったとき、yも２倍になるか調べます。','１辺が１cmのとき、２cmのときのまわりの長さを比べます。'],'１辺が２倍になるとまわりの長さも２倍になるので、比例しています。面積は４倍になるので比例していません。');

  add('proportion','standard','水そうに、１分間に４Lずつ水を入れます。x分間に入る水の量をyLとするとき、６分間ではyはいくつになりますか。',24,[10,4,64],['yはxに比例しています。','y＝４×xです。'],'y＝4 × 6＝24。24Lです。');
  add('proportion','standard','yはxに比例していて、y＝３×xです。yが21のとき、xはいくつですか。',7,[63,18,24],['３×□＝21の□を求めます。','21÷３を計算します。'],'x＝21 ÷ 3＝７です。');
  add('proportion','standard','１個80円のパンをx個買ったときの代金をy円とします。yをxの式で表すと、どれになりますか。','y＝80×x',['y＝x÷80','y＝80＋x','y＝x－80'],['代金＝１個のねだん×個数です。','xは個数です。'],'代金は80×個数なので、y＝80×xです。');
  add('proportion','standard','xとyの関係が表のようになっています。xが１のときのyの値（１あたりの量）はいくつですか。',3,[2,6,18],['xが２のとき、yは６です。','yをxでわって求めます。'],'６÷２＝３。xが１のときのyは３です。',{kind:'table',head:['x','２','４','６'],rows:[['y','６','12','18']],caption:'xとyの関係'});
  add('proportion','standard','yはxに比例していて、xが３のときyは５です。xが９のとき、yはいくつですか。',15,[8,45,11],['xが何倍になっているか見ます。','３から９は３倍です。'],'xが３から９へ３倍になるので、yも３倍になります。5 × 3＝15です。');
  add('proportion','standard','針金３mの重さが12gです。この針金７mの重さは何gですか。',28,[36,84,16],['まず、針金１mの重さを求めます。','12÷３＝４gです。'],'１mの重さは 12 ÷ 3＝４g。７mでは 4 × 7＝28g です。');
  add('proportion','standard','紙10まいの厚さが２mmです。この紙35まいの厚さは何mmですか。',7,[3.5,70,12],['紙１まいの厚さを求めます。','２÷10＝0.2mmです。'],'１まいの厚さは 2 ÷ 10＝0.2mm。35まいでは 0.2 × 35＝７mmです。');
  add('proportion','standard','次のうち、yがxに比例しているものはどれですか。','毎分同じ量ずつ水を入れるときの、時間x分と水の量yL',['60ページの本を読んだページ数xと、のこりのページ数y','たて５cmの長方形の横x cmと、まわりの長さy cm','人の年れいx才と、体重ykg'],['xが２倍になったときにyも２倍になるか考えます。','のこりのページ数は、読むほど減ります。'],'毎分同じ量ずつ入れると、時間が２倍になれば水の量も２倍になるので、比例しています。');
  add('proportion','standard','yはxに比例していて、xが２のときyは９です。xが４のとき、yはいくつですか。',18,[11,13,36],['xが何倍になっているか見ます。','２から４は２倍です。'],'xが２倍になるので、yも２倍になります。9 × 2＝18です。');

  add('proportion','advanced','yはxに比例していて、xが４のときyは14です。yを求める式は y＝□×x です。□にあてはまる数はいくつですか。',3.5,[10,18,56],['□はxが１のときのyの値です。','yをxでわって求めます。'],'14 ÷ 4＝3.5。y＝3.5×xです。');
  add('proportion','advanced','水そうに、毎分20Lずつ水を入れます。水が120L入るのは、何分後ですか。',6,[2400,100,140],['y＝20×x（xは分、yはL）です。','120＝20×xのxを求めます。'],'120 ÷ 20＝６。６分後です。');
  add('proportion','advanced','雪上車は、１時間に48kmの速さで走ります。同じ速さで3.5時間走ると、何km進みますか。',168,[51.5,13.7,144],['進む道のりは、走った時間に比例します。','48 × 3.5を計算します。'],'48 × 3.5＝168。168km進みます。');
  add('proportion','advanced','紙100まいの重さが450gです。同じ紙240まいの重さは何gですか。',1080,[540,1800,108],['まず、紙１まいの重さを求めます。','450÷100＝4.5gです。'],'１まいの重さは 450 ÷ 100＝4.5g。240まいでは 4.5 × 240＝1080g です。');
  add('proportion','advanced','比例のグラフが、（x，y）＝（４，10）の点を通っています。xが６のとき、yはいくつですか。',15,[12,16,24],['xが１のときのyを考えます。','10÷４＝2.5です。'],'y＝2.5×xなので、x＝６のとき 2.5 × 6＝15です。');
  add('proportion','advanced','yはxに比例しています。xが２から５にふえると、yは８から何になりますか。',20,[11,13,40],['xは何倍になっているでしょう。','２から５は2.5倍です。'],'xが 5 ÷ 2＝2.5倍になるので、yも2.5倍。8 × 2.5＝20です。');
  add('proportion','advanced','地図の上の１cmが、実さいの５kmを表しています。地図の上で7.5cmのきょりは、実さいは何kmですか。',37.5,[12.5,35,1.5],['実さいのきょりは、地図の上の長さに比例します。','５×7.5を計算します。'],'5 × 7.5＝37.5。実さいは37.5kmです。');

  // ---- 帯グラフと円グラフ：基礎6・標準9・発展7 ----
  add('graph','basic','全体を長方形の帯にして、それぞれの割合を表したグラフを何といいますか。','帯グラフ',['円グラフ','折れ線グラフ','ぼうグラフ'],['長方形の帯を、割合で区切ります。','円で表すグラフは円グラフです。'],'全体を帯の形にして割合を表したグラフを、帯グラフといいます。');
  add('graph','basic','全体を円にして、それぞれの割合を表したグラフを何といいますか。','円グラフ',['帯グラフ','折れ線グラフ','ぼうグラフ'],['円を、おうぎ形に区切ります。','長方形で表すグラフは帯グラフです。'],'全体を円で表し、割合をおうぎ形で表したグラフを、円グラフといいます。');
  add('graph','basic','帯グラフや円グラフで、全体の割合を合計すると、何％になりますか。',100,[10,50,1],['全体を100％として表しています。','部分の割合を全部足すと全体になります。'],'全体が100％なので、部分の割合の合計も100％になります。');
  add('graph','basic','帯グラフで、木材が40％、鉄が35％、石があとの割合です。石は何％ですか。',25,[75,35,5],['全体は100％です。','40＋35を先に求めます。'],'40＋35＝75。100－75＝25。石は25％です。');
  add('graph','basic','円グラフで、円全体の４分の１を表す部分は、何％ですか。',25,[4,50,14],['100％を４等分します。','100÷４を計算します。'],'100 ÷ 4＝25。25％です。');
  add('graph','basic','円グラフで、半円を表す部分は、何％ですか。',50,[25,75,100],['半分は、全体の何％でしょう。','100％の半分です。'],'100％の半分なので、50％です。');

  add('graph','standard','雪原の町の人口は200人です。そのうち、スキーが好きな人は30％です。スキーが好きな人は何人ですか。',60,[6,30,170],['30％は0.3です。','全体の人数に割合をかけます。'],'200 × 0.3＝60。60人です。');
  add('graph','standard','40人のクラスで、すきな教科を調べました。国語は25％でした。国語がすきな人は何人ですか。',10,[25,15,100],['25％は、全体の４分の１です。','40 × 0.25を計算します。'],'40 × 0.25＝10。10人です。');
  add('graph','standard','集めた資源が全部で400こあります。そのうち、木材は45％です。木材は何こですか。',180,[45,220,18],['45％は0.45です。','400 × 0.45を計算します。'],'400 × 0.45＝180。180こです。');
  add('graph','standard','全体が250こで、そのうちの50このものがあります。その割合は、何％ですか。',20,[5,50,200],['割合＝部分÷全体です。','50÷250を計算して、100をかけます。'],'50 ÷ 250＝0.2。0.2は20％です。');
  add('graph','standard','全体が500人で、ある部分が12％です。その部分は何人ですか。',60,[12,6,488],['12％は0.12です。','500 × 0.12を計算します。'],'500 × 0.12＝60。60人です。');
  add('graph','standard','町の人口120人のうち、子どもは15％です。子どもは何人ですか。',18,[15,8,105],['15％は0.15です。','120 × 0.15を計算します。'],'120 × 0.15＝18。18人です。');
  add('graph','standard','円グラフで、４つの項目の割合が35％、25％、20％と、あと１つです。あとの１つは何％ですか。',20,[80,25,15],['全部の割合を足すと100％です。','35＋25＋20を先に求めます。'],'35＋25＋20＝80。100－80＝20。あとの１つは20％です。');
  add('graph','standard','去年は木材が30％、今年は35％でした。今年は去年より、何％分ふえましたか。',5,[65,30,35],['割合どうしのちがいを求めます。','35から30を引きます。'],'35－30＝５。５％分ふえました。');
  add('graph','standard','全部で80人のクラスで、図書委員は全体の５％です。図書委員は何人ですか。',4,[5,40,76],['５％は0.05です。','80 × 0.05を計算します。'],'80 × 0.05＝４。４人です。');

  add('graph','advanced','全体が600人で、ある部分が18％です。その部分は何人ですか。',108,[18,118,60],['18％は0.18です。','600 × 0.18を計算します。'],'600 × 0.18＝108。108人です。');
  add('graph','advanced','円グラフで、円の中心の角が90°の部分は、全体の何％ですか。',25,[9,50,90],['円全体の中心の角は360°です。','90÷360を計算します。'],'90 ÷ 360＝0.25。25％です。');
  add('graph','advanced','円グラフで、全体の10％を表す部分の、円の中心の角は何度ですか。',36,[10,100,18],['円全体の中心の角は360°です。','360 × 0.1を計算します。'],'360 × 0.1＝36。36°です。');
  add('graph','advanced','町の人口は2400人です。{若|わか}い人の割合が35％、お年寄りの割合が15％のとき、{若|わか}い人はお年寄りより何人多いですか。',480,[20,840,360],['それぞれの人数を求めます。','2つの人数のちがいを求めます。'],'{若|わか}い人は 2400 × 0.35＝840人、お年寄りは 2400 × 0.15＝360人。840－360＝480。480人多いです。');
  add('graph','advanced','30人に好きなスポーツを聞くと、スキーが12人、スケートが９人、そりが６人、その他が３人でした。スキーは全体の何％ですか。',40,[12,25,60],['割合＝部分÷全体です。','12÷30を計算します。'],'12 ÷ 30＝0.4。0.4は40％です。');
