  add('circle','basic','半径が５cmの円の直径は何cmですか。',10,[2.5,5,15],['直径は半径の２倍です。','５×２を計算します。'],'5 × 2＝10。直径は10cmです。');

  add('circle','standard','直径が20cmの円の円周は何cmですか。（円周率は3.14）',62.8,[23.14,6.28,628],['円周＝直径×円周率です。','20 × 3.14を計算します。'],'20 × 3.14＝62.8。円周は62.8cmです。');
  add('circle','standard','半径が５cmの円の円周は何cmですか。（円周率は3.14）',31.4,[15.7,78.5,314],['先に直径を求めます。','円周＝直径×円周率です。'],'直径は 5 × 2＝10cm。10 × 3.14＝31.4。円周は31.4cmです。');
  add('circle','standard','円周が12.56cmの円の直径は何cmですか。（円周率は3.14）',4,[2,8,39.4],['円周＝直径×円周率です。','円周を円周率でわります。'],'12.56 ÷ 3.14＝４。直径は４cmです。');
  add('circle','standard','直径が８cmの円の円周は何cmですか。（円周率は3.14）',25.12,[11.14,50.24,251.2],['円周＝直径×円周率です。','８×3.14を計算します。'],'8 × 3.14＝25.12。円周は25.12cmです。');
  add('circle','standard','１辺が５cmの正六角形のまわりの長さは何cmですか。',30,[25,35,15],['正六角形は、辺が６本あります。','全部の辺の長さが等しいです。'],'5 × 6＝30。まわりの長さは30cmです。');
