  add('fraction','standard','1/6＋1/3を計算しましょう。','1/2',['2/9','2/6','1/9'],['分母を６にそろえます。','答えは、約分できます。'],'1/3＝2/6。1/6＋2/6＝3/6＝1/2です。');
