  add('fraction','standard','１と2/5＋3/10を計算しましょう。','１と7/10',['１と5/15','１と1/2','２と1/10'],['分数の部分を、分母10にそろえます。','2/5＝4/10です。'],'2/5＝4/10。１と4/10＋3/10＝１と7/10です。');
  add('fraction','standard','３－1/4を計算しましょう。','２と3/4',['２と1/4','３と1/4','2/4'],['３から１をかりて、4/4と考えます。','３＝２と4/4です。'],'３＝２と4/4。２と4/4－1/4＝２と3/4です。');
  add('fraction','standard','2/3＋3/5を計算しましょう。','１と4/15',['5/8','１と1/15','１と9/15'],['分母を15にそろえます。','３と５の最小公倍数は15です。'],'2/3＝10/15、3/5＝9/15。10/15＋9/15＝19/15＝１と4/15です。');
  add('fraction','standard','7/8－1/4を計算しましょう。','5/8',['6/4','6/8','3/4'],['分母を８にそろえます。','1/4は、何分の何と同じでしょう。'],'1/4＝2/8。7/8－2/8＝5/8です。');

