  add('fraction','advanced','１mのひもから、1/3mと1/4mを切り取りました。のこりは何mですか。','5/12m',['7/12m','5/7m','2/7m'],['切り取った長さを、先に合わせます。','1/3＋1/4を計算して、１から引きます。'],'1/3＋1/4＝4/12＋3/12＝7/12。１－7/12＝5/12。5/12mです。');
  add('fraction','advanced','□＋1/3＝5/6です。□にあてはまる分数はいくつですか。','1/2',['1/6','1/3','7/6'],['□は、ひき算で求めます。','5/6－1/3を計算します。'],'□＝5/6－1/3＝5/6－2/6＝3/6＝1/2です。');
  add('fraction','advanced','□－2/5＝1/10です。□にあてはまる分数はいくつですか。','1/2',['3/10','3/5','1/4'],['□は、たし算で求めます。','1/10＋2/5を計算します。'],'□＝1/10＋2/5＝1/10＋4/10＝5/10＝1/2です。');
  add('fraction','advanced','水そうＡに2/3L、水そうＢに3/4Lの水があります。どちらが何L多いですか。','Ｂが1/12L多い',['Ａが1/12L多い','Ｂが1/6L多い','Ａが1/6L多い'],['分母を12にそろえて比べます。','2/3＝8/12、3/4＝9/12です。'],'2/3＝8/12、3/4＝9/12。9/12－8/12＝1/12。Ｂが1/12L多いです。');
  add('fraction','advanced','雪とかしの仕事を、１日目に全体の1/3、２日目に全体の1/4やりました。のこりは全体のどれだけですか。','5/12',['7/12','2/7','1/12'],['やった仕事を合わせてから、全体の１から引きます。','1/3＋1/4を、先に計算します。'],'1/3＋1/4＝7/12。１－7/12＝5/12です。');
  add('fraction','advanced','1/6＋1/10を計算しましょう。','4/15',['2/16','2/60','1/15'],['分母を30にそろえます。','答えは、約分できます。'],'1/6＝5/30、1/10＝3/30。5/30＋3/30＝8/30＝4/15です。');
  add('fraction','advanced','４と1/5＋２と3/10を計算しましょう。','６と1/2',['６と4/15','６と4/10','７と1/2'],['整数の部分と、分数の部分に分けて計算します。','1/5＝2/10です。'],'整数は ４＋２＝６、分数は 2/10＋3/10＝5/10＝1/2。６と1/2です。');
  add('fraction','advanced','5/6＋１と1/4を計算しましょう。','２と1/12',['１と6/10','２と5/12','２と1/6'],['帯分数を、仮分数にしてもよいです。','分母を12にそろえます。'],'5/6＝10/12、１と1/4＝１と3/12。10/12＋１と3/12＝１と13/12＝２と1/12です。');
  add('fraction','advanced','雪原のパトロールで、行きに1/2km、まん中に1/3km、帰りに1/4km歩きました。全部で何km歩きましたか。','１と1/12km',['3/9km','13/24km','１と1/9km'],['３つの分数を、通分してたします。','分母を12にそろえます。'],'1/2＝6/12、1/3＝4/12、1/4＝3/12。6/12＋4/12＋3/12＝13/12＝１と1/12。１と1/12kmです。');

