  add('intdec','basic','3.45の10倍はいくつですか。',34.5,[0.345,345,3.45],['10倍すると、小数点が右へ１けたうつります。','3.45の小数点を、右へ１けた動かします。'],'小数点が右へ１けたうつるので、34.5です。');
  add('intdec','basic','3.45の100倍はいくつですか。',345,[34.5,0.345,3450],['100倍すると、小数点が右へ２けたうつります。','3.45の小数点を、右へ２けた動かします。'],'小数点が右へ２けたうつるので、345です。');
  add('intdec','basic','3.45の10分の１はいくつですか。',0.345,[34.5,0.0345,345],['10分の１にすると、小数点が左へ１けたうつります。','3.45の小数点を、左へ１けた動かします。'],'小数点が左へ１けたうつるので、0.345です。');
  add('intdec','basic','0.6の10倍はいくつですか。',6,[60,0.06,0.6],['10倍すると、小数点が右へ１けたうつります。','0.6の小数点を、右へ１けた動かします。'],'小数点が右へ１けたうつるので、６です。');
  add('intdec','basic','2.5の100倍はいくつですか。',250,[25,2500,0.25],['100倍すると、小数点が右へ２けたうつります。','右にたりないけたは、０を書きます。'],'小数点が右へ２けたうつるので、250です。');
  add('intdec','basic','4.8の10分の１はいくつですか。',0.48,[48,0.048,4.8],['10分の１にすると、小数点が左へ１けたうつります。','4.8の小数点を、左へ１けた動かします。'],'小数点が左へ１けたうつるので、0.48です。');

  add('intdec','standard','ある数の小数点を、右へ１けたうつすと、もとの数の何倍になりますか。',10,[100,1,2],['10倍、100倍などを考えます。','右へ１けたうつすと、位が１つ上がります。'],'小数点が右へ１けたうつると、もとの数の10倍になります。');
  add('intdec','standard','0.07の100倍はいくつですか。',7,[0.7,70,0.0007],['100倍すると、小数点が右へ２けたうつります。','0.07の小数点を、右へ２けた動かします。'],'小数点が右へ２けたうつるので、７です。');
  add('intdec','standard','520の100分の１はいくつですか。',5.2,[52,0.52,0.052],['100分の１にすると、小数点が左へ２けたうつります。','520は、520.0と考えます。'],'小数点が左へ２けたうつるので、5.2です。');
  add('intdec','standard','12.5の1000分の１はいくつですか。',0.0125,[0.125,0.00125,0.0012],['1000分の１にすると、小数点が左へ３けたうつります。','左にたりないけたは、０を書きます。'],'小数点が左へ３けたうつるので、0.0125です。');
  add('intdec','standard','6.38の小数第２位の数字は、いくつですか。',3,[6,8,38],['小数第１位は、小数点のすぐ右の位です。','小数第２位は、その次の位です。'],'6.38の小数第１位は３、小数第２位は８です。'.replace('３、小数第２位は８','３、小数第２位は８'));
  add('intdec','standard','0.001を1000こ集めた数はいくつですか。',1,[0.1,10,100],['0.001が10こで0.01になります。','1000倍すると、小数点が右へ３けたうつります。'],'0.001 × 1000＝１です。');
  add('intdec','standard','4.06は、0.01を何こ集めた数ですか。',406,[46,4.06,40.6],['0.01を100こ集めると、１になります。','4.06を100倍すると、いくつでしょう。'],'4.06 ÷ 0.01＝406。0.01が406こ集まった数です。');
  add('intdec','standard','0.1を35こ集めた数はいくつですか。',3.5,[35,0.35,3.05],['0.1が10こで１です。','35×0.1を計算します。'],'0.1 × 35＝3.5です。');
  add('intdec','standard','ある数の小数点を右へ１けたうつしたら、4.5になりました。もとの数はいくつですか。',0.45,[45,0.045,4.05],['10倍して4.5になった数です。','4.5を10でわります。'],'もとの数は 4.5 ÷ 10＝0.45です。');

  add('intdec','advanced','2.305は、0.001を何こ集めた数ですか。',2305,[235,23.05,305],['0.001を1000こ集めると、１になります。','2.305を1000倍します。'],'2.305 × 1000＝2305。0.001が2305こ集まった数です。');
  add('intdec','advanced','ある数を10倍したら、7.2になりました。もとの数はいくつですか。',0.72,[72,0.072,7.02],['もとの数は、7.2を10でわった数です。','小数点を左へ１けたうつします。'],'もとの数は 7.2 ÷ 10＝0.72です。');
  add('intdec','advanced','ある数の100分の１が0.063です。ある数はいくつですか。',6.3,[0.63,63,0.00063],['ある数は、0.063を100倍した数です。','小数点を右へ２けたうつします。'],'ある数は 0.063 × 100＝6.3です。');
  add('intdec','advanced','1.5kmは、何mですか。',1500,[150,15,15000],['１km＝1000mです。','1.5を1000倍します。'],'1.5 × 1000＝1500。1500mです。');
  add('intdec','advanced','3.6kgの1000分の１は、何gですか。',3.6,[0.36,36,0.0036],['3.6kgは、何gでしょう。','３.6kg＝3600gです。'.replace('３','3')],'3.6kg＝3600g。3600 ÷ 1000＝3.6。3.6gです。');
  add('intdec','advanced','0.04を100倍した数は、0.4の何倍ですか。',10,[100,1,0.1],['それぞれの数を計算してから、比べます。','0.04×100＝４です。'],'0.04 × 100＝４。４ ÷ 0.4＝10。10倍です。');
  add('intdec','advanced','35.7を10倍した数を、さらに100分の１にすると、いくつになりますか。',3.57,[357,35.7,0.357],['10倍して100分の１にすると、結局、何分の１になるでしょう。','小数点を、右へ１けた、左へ２けたうつします。'],'35.7 × 10＝357。357 ÷ 100＝3.57です。');

  // ---- 倍数と約数：基礎6・標準9・発展7 ----
  add('multiple','basic','10、12、14、16のうち、３の倍数は何ですか。',12,[10,14,16],['３のだんの九九に出てくる数です。','３でわりきれる数を選びます。'],'12 ÷ 3＝４で、わりきれます。12は３の倍数です。');
  add('multiple','basic','12の約数のうち、いちばん大きい数はいくつですか。',12,[6,4,1],['約数は、わりきれる数のことです。','自分自身も約数です。'],'12の約数は 1、2、3、4、6、12。いちばん大きいのは12です。');
  add('multiple','basic','６と９の最小公倍数はいくつですか。',18,[3,36,54],['６の倍数と９の倍数を、小さい順にならべます。','６、12、18…と、９、18…です。'],'６の倍数は 6、12、18…、９の倍数は 9、18…。いちばん小さい共通の倍数は18です。');
  add('multiple','basic','８と12の最大公約数はいくつですか。',4,[2,24,1],['８の約数と12の約数を書き出します。','共通の約数のうち、いちばん大きい数です。'],'８の約数は 1、2、4、8、12の約数は 1、2、3、4、6、12。共通で最大は４です。');
  add('multiple','basic','10の約数は、全部でいくつありますか。',4,[2,3,5],['10をわりきれる数を、すべて書き出します。','１と10も入れます。'],'10の約数は 1、2、5、10の４こです。');
  add('multiple','basic','14、16、18、22のうち、４の倍数は何ですか。',16,[14,18,22],['４のだんの九九に出てくる数です。','４でわりきれる数を選びます。'],'16 ÷ 4＝４で、わりきれます。16は４の倍数です。');

  add('multiple','standard','４と６の公倍数のうち、いちばん小さい数はいくつですか。',12,[2,24,10],['４の倍数と６の倍数を、小さい順にならべます。','共通の倍数のうち、いちばん小さい数です。'],'４の倍数は 4、8、12…、６の倍数は 6、12…。最小公倍数は12です。');
  add('multiple','standard','12と18の最大公約数はいくつですか。',6,[3,36,2],['12の約数と18の約数を書き出します。','共通の約数のうち、いちばん大きい数です。'],'12の約数は 1、2、3、4、6、12、18の約数は 1、2、3、6、9、18。共通で最大は６です。');
  add('multiple','standard','15と20の最小公倍数はいくつですか。',60,[5,30,300],['15の倍数と20の倍数を、小さい順にならべます。','15、30、45、60…と、20、40、60…です。'],'15の倍数は 15、30、45、60…、20の倍数は 20、40、60…。最小公倍数は60です。');
  add('multiple','standard','24の約数は、全部でいくつありますか。',8,[6,4,12],['24をわりきれる数を、すべて書き出します。','１と24も入れます。'],'24の約数は 1、2、3、4、6、8、12、24の８こです。');
  add('multiple','standard','１から30までの整数の中に、５の倍数は何こありますか。',6,[5,7,30],['５、10、15…と書き出します。','30÷５を計算します。'],'５の倍数は 5、10、15、20、25、30の６こです。');
  add('multiple','standard','{奇数|きすう}と{奇数|きすう}をたした答えは、{偶数|ぐうすう}と{奇数|きすう}のどちらですか。','{偶数|ぐうすう}',['{奇数|きすう}','{偶数|ぐうすう}のときも{奇数|きすう}のときもある','どちらでもない'],['たとえば、３＋５を計算してみます。','１＋３、３＋７も試します。'],'{奇数|きすう}どうしをたすと、いつも{偶数|ぐうすう}になります。（例：3＋5＝８）');
  add('multiple','standard','たて18cm、横24cmの長方形の紙を、同じ大きさの正方形に、あまりが出ないように切ります。いちばん大きい正方形の１辺は何cmですか。',6,[3,72,2],['１辺は、18と24の公約数です。','いちばん大きい、というのは、最大公約数です。'],'18と24の最大公約数は６です。１辺は６cmです。');
  add('multiple','standard','バスの発着場で、Ａ路線は６分おき、Ｂ路線は８分おきに出ます。２つが同時に出発したあと、次に同時に出発するのは、何分後ですか。',24,[2,14,48],['６の倍数と８の倍数を書き出します。','最小公倍数を求めます。'],'６と８の最小公倍数は24です。24分後に、また同時に出発します。');
  add('multiple','standard','１から10までの整数の中に、素数は何こありますか。',4,[3,5,6],['素数は、１と自分自身しか約数がない数です。','１は素数ではありません。'],'２、３、５、７の４こです。');

  add('multiple','advanced','４、６、９の最小公倍数はいくつですか。',36,[18,24,72],['まず、大きい数９の倍数から、順に調べます。','９、18、27、36…で、４と６でわれる数を探します。'],'９の倍数のうち、４でも６でもわりきれる最小の数は、36です。');
  add('multiple','advanced','24と36の最大公約数はいくつですか。',12,[6,4,72],['24の約数と36の約数を書き出します。','または、２、３でわっていきます。'],'24の約数と36の約数の共通で最大の数は12です。');
  add('multiple','advanced','雪原の子ども40人と56人を、それぞれ同じ人数ずつのグループに分けます。できるだけ多い人数のグループにすると、１グループは何人ですか。',8,[4,16,280],['40と56の、公約数を考えます。','いちばん大きい、というのは最大公約数です。'],'40と56の最大公約数は８です。１グループは８人です。');
  add('multiple','advanced','１から100までの整数の中に、３と４の公倍数は何こありますか。',8,[7,9,33],['まず、３と４の最小公倍数を求めます。','その倍数が、100までにいくつあるか数えます。'],'３と４の最小公倍数は12。12の倍数は 12、24、36、48、60、72、84、96の８こです。');
  add('multiple','advanced','たて12cm、横20cmの長方形の紙を、あまりが出ないように、同じ大きさの正方形に切ります。いちばん大きい正方形に切ると、何まいできますか。',15,[4,5,60],['12と20の最大公約数が、正方形の１辺です。','たてと横に、それぞれ何まい切れるか考えます。'],'最大公約数は４なので、１辺は４cmです。たてに３まい、横に５まい。3 × 5＝15まいです。');
  add('multiple','advanced','５でわると３あまり、６でわると３あまる数のうち、３より大きいいちばん小さい数はいくつですか。',33,[18,30,63],['５と６の最小公倍数を考えます。','その数に、あまりの３を足します。'],'５と６の最小公倍数は30。30＋3＝33です。');
